import type { ModuleId } from '@/lib/modules/registry';

export interface EndpointDoc {
  method: string;
  path: string;
  description: string;
  group: string;
  params?: { name: string; type: string; required: boolean; description: string }[];
  queryParams?: { name: string; type: string; description: string }[];
  body?: { name: string; type: string; required: boolean; description: string }[];
}

export function getEndpointScopes(endpoint: EndpointDoc): string[] {
  const { method, path } = endpoint;
  const write = method !== 'GET' && method !== 'HEAD';

  if (path === '/api/v1/inbox/meetings') return ['meetings.write'];
  if (path.startsWith('/api/v1/delegations')) return ['agents.act_for'];
  if (path === '/api/v1/identities/link-requests') return ['identities.link'];
  if (path === '/api/v1/identities' || path.startsWith('/api/v1/identities/:id')) return ['team.manage'];
  if (path.startsWith('/api/v1/identities') || path.endsWith('/identities')) return ['identities.read'];
  if (path.startsWith('/api/v1/groups')) return write ? ['groups.manage'] : ['team.read', 'team.manage', 'groups.manage'];
  if (path === '/api/v1/api-keys/:id/rotate') return ['api_keys.manage_all', 'assistants.provision'];
  if (path.startsWith('/api/v1/api-keys')) return ['api_keys.manage_all'];
  if (path.startsWith('/api/v1/assistant/')) return ['notifications.manage_own'];
  if (path.startsWith('/api/v1/assistants') || path.startsWith('/api/v1/assistant-setups')) return ['assistants.provision'];
  if (path.startsWith('/api/v1/webhook-endpoints')) return ['webhooks.manage'];
  if (path === '/api/v1/agents') return method === 'GET' ? ['team.read', 'team.manage'] : ['team.manage'];
  if (path === '/api/v1/agents/:id' || path === '/api/v1/agents/roles') return ['team.read', 'team.manage'];
  if (path === '/api/v1/agents/me/projects') return ['any scope'];
  if (path === '/api/v1/projects/:id/agents') return ['projects.read', 'projects.read_all', 'projects.manage'];
  if (path === '/api/v1/projects/:id/agents/:agentId') return ['project_members.manage', 'team.read (an owner of the agent)'];
  if (path === '/api/v1/agents/:id/setup') return ['team.read', 'team.manage'];
  if (path === '/api/v1/agents/:id/projects') return ['project_members.manage'];
  if (path === '/api/v1/agents/me/context' || path === '/api/v1/mcp/tools') return ['any scope'];
  if (path === '/api/v1/agents/:id/context' || path === '/api/v1/agents/:id/export') return ['team.read', 'team.manage'];
  if (path === '/api/v1/agents/:id/template' || path === '/api/v1/agents/import' || path === '/api/v1/agent-templates') return ['team.manage'];
  if (path === '/api/v1/agent-profiles' && !write) return ['team.read', 'team.manage'];
  if (path.startsWith('/api/v1/agent-profiles') || path.startsWith('/api/v1/agent-templates/') || path.startsWith('/api/v1/agent-registries')) return ['team.manage'];
  if (path === '/api/v1/tasks/:id/delegate') return ['tasks.create', 'tasks.manage_all'];
  if (path === '/api/v1/agents/runs/:id/tree') return ['agent_activity.write', 'tasks.read', 'agents.manage'];
  if (path === '/api/v1/context' || path === '/api/v1/context/search' || path === '/api/v1/context/:entryId') return ['any scope'];
  if (path.includes('/inbound-emails') || path.startsWith('/api/v1/inbox/') || path === '/api/v1/tasks/:id/messages') {
    if (path.endsWith('/signal')) return ['inbound_email.signal'];
    if (path.endsWith('/messages/:id/tasks')) return ['tasks.create', 'inbound_email.triage'];
    return write ? ['inbound_email.triage'] : ['inbound_email.read'];
  }
  if (path.includes('/client-notifications')) return ['communications.manage'];
  if (path.includes('/communications')) return [write ? 'communications.manage' : 'communications.read'];
  if (path.endsWith('/time-entries/review')) return ['time.approve'];
  if (path.includes('/hourly-rates')) return ['billing.manage'];
  if (path.includes('/payments')) return write ? ['invoices.record_payments', 'invoices.manage'] : ['invoices.read', 'invoices.manage'];
  if (path === '/api/v1/billing/earned-work') return ['invoices.read', 'invoices.manage'];
  if (path.includes('/invoices')) return write ? ['invoices.manage'] : ['invoices.read', 'invoices.manage'];
  if (path === '/api/v1/agent-activities') {
    return write ? ['agent_activity.write', 'fleet_alerts.write'] : ['audit.read'];
  }
  if (path === '/api/v1/agent-activities/:id/labels') return ['agent_activity.write', 'agents.manage'];
  if (path === '/api/v1/agent-events/export') return ['agent_events.export'];
  if (path === '/api/v1/agents/heartbeat') return ['agent_activity.write', 'tasks.read'];
  if (path.startsWith('/api/v1/agents/runs')) return ['agent_activity.write', 'tasks.read', 'agents.manage'];
  if (path === '/api/v1/agents/health') return ['agents.manage'];
  if (path.includes('/task-suggestions')) {
    if (method === 'POST' && path === '/api/v1/task-suggestions') return ['suggestions.create'];
    if (method === 'GET' || method === 'PATCH') return ['suggestions.create', 'suggestions.manage'];
    return ['suggestions.manage'];
  }
  if (path.includes('/credentials')) {
    return path.endsWith('/reveal') || !write
      ? ['credentials.reveal_shared', 'credentials.manage']
      : ['credentials.manage'];
  }
  if (path.includes('/reminders')) return ['reminders.manage_own'];
  if (path.includes('/questions')) return ['tasks.read', 'tasks.manage_all'];
  if (path.includes('/notifications')) {
    if (method === 'POST' && path === '/api/v1/notifications') return ['notifications.send'];
    return ['notifications.manage_own'];
  }
  if (path.includes('/time-entries')) {
    return write
      ? ['time.manage_own', 'time.manage_all']
      : ['time.manage_own', 'time.read_all', 'time.manage_all'];
  }
  if (/^\/api\/v1\/tasks\/:id\/files/.test(path)) {
    if (method === 'GET') return ['files.read', 'files.manage'];
    return method === 'POST' ? ['files.upload'] : ['files.upload', 'files.manage'];
  }
  if (path.includes('/tasks')) {
    if (!write) return ['tasks.read', 'tasks.manage_all'];
    if (path === '/api/v1/tasks' && method === 'POST') return ['tasks.create'];
    if (/\/api\/v1\/tasks\/:id$/.test(path) && method === 'DELETE') return ['tasks.manage_all'];
    if (path.includes('/comments')) return ['tasks.read', 'tasks.manage_all'];
    return ['tasks.manage_assigned', 'tasks.manage_all'];
  }
  if (path.includes('/leads')) return write ? ['leads.manage'] : ['leads.read', 'leads.read_all', 'leads.manage'];
  if (path.includes('/contacts')) return write ? ['contacts.manage'] : ['contacts.read', 'contacts.read_all', 'contacts.manage'];
  if (path.includes('/entity-files')) return method === 'POST' ? ['files.upload'] : write ? ['files.manage'] : ['files.read', 'files.manage'];
  if (path.includes('/portal')) return write ? ['portal.manage'] : ['portal.read', 'portal.manage'];
  if (path.includes('/context')) return write ? ['project_context.manage'] : ['project_context.read', 'project_context.manage'];
  if (path.includes('/goals')) return write ? ['goals.manage'] : ['goals.read', 'goals.manage'];
  if (path === '/api/v1/audit/export') return ['audit.export'];
  if (path.includes('/audit-log') || path.includes('/activities')) return ['audit.read'];
  if (path.includes('/team-members')) return write ? ['team.manage'] : ['team.read', 'team.manage'];
  return write ? ['projects.manage'] : ['projects.read', 'projects.read_all', 'projects.manage'];
}

